import pandas as pdimport matplotlib.pyplot as pltimport numpy as npfrom matplotlib.gridspec import GridSpecimport sys# import matplotlib.pyplot as pltfrom matplotlib import rcrc('font',**{'family':'serif','serif':['Palatino']})plt.rcParams['pdf.fonttype'] = 42fig = plt.figure()# gs=GridSpec(nrows=3, ncols=4)gs=GridSpec(nrows=5, ncols=2)fileName = "validationConvergenceCurves.pdf"all_dataset_name = ['HH', 'HL', 'LH', 'LL']# algos = ['MTGP', 'GPLS']# algos = ['MTGP']# all_dataset_name = ['HL']algos = ['GP']gens = 51for i in range(0, len(all_dataset_name)):    if i<2:        ax = fig.add_subplot(gs[0:2, i])    else:        ax = fig.add_subplot(gs[2:4, i-2])    dataset_name = all_dataset_name[i]    title = 'On dataset ' + all_dataset_name[i]    plt.gca().set_title(title, fontweight='bold', size=9)    labels = algos    for algo in range(0, len(algos)):        address = '../experiment_result/scenario_' + dataset_name + '/all_run_test_results_' + dataset_name + '.xlsx'        results = pd.read_excel(address, engine='openpyxl')        print(results)        ax.plot(range(0,gens), list(results[algos[algo]]), linestyle = '-', linewidth= 0.5, marker ='.', markersize = 5)plt.figlegend(labels, loc = 'lower center', ncol = 3, bbox_to_anchor = (0.53, 0.02), labelspacing=0., fontsize = 'small')fig.text(0.5, 0.12, 'Generation', ha='center', size = 11, fontweight='bold')fig.text(0, 0.54, 'Cumulative tardiness', va='center', rotation='vertical', size = 11, fontweight='bold')plt.tight_layout()plt.savefig("../paintingAnalysis/" + fileName)# plt.savefig("test.png")plt.show()